"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import type {
  DictionaryItem,
  DictionaryMeta,
  LehceTipi,
  AramaModu,
} from "@/types/dictionary";

// Arama esnasında yüksek performans için kullanılan local normalizasyon tipi
interface LocalNormalizedItem {
  item: DictionaryItem;
  normalizedKelime: string;
  normalizedTanim: string;
}

export function useDictionary() {
  const [loading, setLoading] = useState<boolean>(true);
  const [rawItems, setRawItems] = useState<DictionaryItem[]>([]);
  const [aktifSozlukler, setAktifSozlukler] = useState<DictionaryMeta[]>([]);
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [seciliLehce, setSeciliLehce] = useState<LehceTipi>("TUMU");
  const [seciliDosya, setSeciliDosya] = useState<string>("tumu");
  const [gununKelimesi, setGununKelimesi] = useState<DictionaryItem | null>(null);

  // Metin Normalizasyonu (Çerkesçe karakter & Türkçe harf uyumu)
  const normalizeText = useCallback((str: string = ""): string => {
    return str
      .toLowerCase()
      .replace(/I/g, "ı")
      .replace(/İ/g, "i")
      .trim();
  }, []);

  // Tanım Öncelik Hiyerarşisi Ayrıştırıcı
  const extractTanimMetni = useCallback((item: DictionaryItem): string => {
    return (
      item.definitions?.[0]?.meaning ||
      item.full_definition_in_html ||
      (typeof item.tanim === "string" ? item.tanim : "") ||
      item.meaning ||
      ""
    );
  }, []);

  // Performanslı Arama İndeksi: Arama verilerini hafızada yerel olarak indeksleme
  const normalizedIndex = useMemo<LocalNormalizedItem[]>(() => {
    return rawItems.map((item) => ({
      item,
      normalizedKelime: normalizeText(item.kelime),
      normalizedTanim: normalizeText(extractTanimMetni(item)),
    }));
  }, [rawItems, normalizeText, extractTanimMetni]);

  // Filtreleme Mantığı
  const filtrelenmisSonuclar = useMemo<DictionaryItem[]>(() => {
    if (!searchQuery.trim()) return [];

    const query = normalizeText(searchQuery);

    return normalizedIndex
      .filter(({ item, normalizedKelime, normalizedTanim }) => {
        // Lehçe Filtresi
        if (seciliLehce !== "TUMU" && item.dialect !== seciliLehce) {
          return false;
        }

        // Dosya / Kaynak Sözlük Filtresi
        if (seciliDosya !== "tumu" && item.file !== seciliDosya) {
          return false;
        }

        // Arama Eşleşmesi
        return (
          normalizedKelime.includes(query) || normalizedTanim.includes(query)
        );
      })
      .map((entry) => entry.item);
  }, [searchQuery, seciliLehce, seciliDosya, normalizedIndex, normalizeText]);

  return {
    loading,
    searchQuery,
    setSearchQuery,
    seciliLehce,
    setSeciliLehce,
    seciliDosya,
    setSeciliDosya,
    gununKelimesi,
    filtrelenmisSonuclar,
    aktifSozlukler,
    wordsCount: rawItems.length,
  };
}